func expand5Salt(st *[5]state, words *[5][18]uint32, salts *[5][18]uint32) {
	for k := range 5 {
		for i := range 18 {
			st[k].p[i] ^= words[k][i]
		}
	}
	var l, r [5]uint32
	saltIndex := 0
	for i := 0; i < 18; i += 2 {
		for k := range 5 {
			l[k] ^= salts[k][saltIndex&3]
			r[k] ^= salts[k][(saltIndex+1)&3]
		}
		saltIndex += 2
		encrypt5(st, &l, &r)
		for k := range 5 {
			st[k].p[i], st[k].p[i+1] = l[k], r[k]
		}
	}
	for i := 0; i < 256; i += 2 {
		for k := range 5 {
			l[k] ^= salts[k][saltIndex&3]
			r[k] ^= salts[k][(saltIndex+1)&3]
		}
		saltIndex += 2
		encrypt5(st, &l, &r)
		for k := range 5 {
			st[k].s0[i], st[k].s0[i+1] = l[k], r[k]
		}
	}
	for i := 0; i < 256; i += 2 {
		for k := range 5 {
			l[k] ^= salts[k][saltIndex&3]
			r[k] ^= salts[k][(saltIndex+1)&3]
		}
		saltIndex += 2
		encrypt5(st, &l, &r)
		for k := range 5 {
			st[k].s1[i], st[k].s1[i+1] = l[k], r[k]
		}
	}
	for i := 0; i < 256; i += 2 {
		for k := range 5 {
			l[k] ^= salts[k][saltIndex&3]
			r[k] ^= salts[k][(saltIndex+1)&3]
		}
		saltIndex += 2
		encrypt5(st, &l, &r)
		for k := range 5 {
			st[k].s2[i], st[k].s2[i+1] = l[k], r[k]
		}
	}
	for i := 0; i < 256; i += 2 {
		for k := range 5 {
			l[k] ^= salts[k][saltIndex&3]
			r[k] ^= salts[k][(saltIndex+1)&3]
		}
		saltIndex += 2
		encrypt5(st, &l, &r)
		for k := range 5 {
			st[k].s3[i], st[k].s3[i+1] = l[k], r[k]
		}
	}
}
func Sum5(passwords [5][]byte, salts [5][16]byte, cost uint) (result [5][23]byte) {
	if cost < 4 || cost > 16 {
		panic("bcrypt lane cost must be 4..16")
	}
	var st [5]state
	var keys, saltWords [5][18]uint32
	for k := range 5 {
		if len(passwords[k]) > 72 {
			panic("bcrypt lane passwords must be <=72 bytes")
		}
		var key [73]byte
		copy(key[:], passwords[k])
		keys[k], saltWords[k] = keyWords(key[:len(passwords[k])+1]), keyWords(salts[k][:])
		st[k] = state{p: p, s0: s0, s1: s1, s2: s2, s3: s3}
	}
	expand5Salt(&st, &keys, &saltWords)
	for rounds := 0; rounds < 1<<cost; rounds++ {
		expand5(&st, &keys)
		expand5(&st, &saltWords)
	}
	var text [5][6]uint32
	for k := range 5 {
		text[k] = [6]uint32{0x4f727068, 0x65616e42, 0x65686f6c, 0x64657253, 0x63727944, 0x6f756274}
	}
	for block := range 3 {
		var l, r [5]uint32
		for k := range 5 {
			l[k], r[k] = text[k][2*block], text[k][2*block+1]
		}
		for range 64 {
			encrypt5(&st, &l, &r)
		}
		for k := range 5 {
			text[k][2*block], text[k][2*block+1] = l[k], r[k]
		}
	}
	for k := range 5 {
		var raw [24]byte
		for i, word := range text[k] {
			binary.BigEndian.PutUint32(raw[i*4:], word)
		}
		copy(result[k][:], raw[:23])
	}
	return
}
